CREATE TYPE "public"."review_source" AS ENUM('ozon', 'site');--> statement-breakpoint
CREATE TABLE "reviews" (
	"id" text PRIMARY KEY NOT NULL,
	"source" "review_source" DEFAULT 'ozon' NOT NULL,
	"rating" integer NOT NULL,
	"text" text NOT NULL,
	"reviewer_name" text NOT NULL,
	"product_offer_id" text,
	"product_title" text,
	"photos" text[] DEFAULT '{}'::text[] NOT NULL,
	"reviewed_at" timestamp with time zone NOT NULL,
	"published" boolean DEFAULT false NOT NULL,
	"show_photos" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "reviews_rating_range" CHECK ("reviews"."rating" BETWEEN 1 AND 5)
);
--> statement-breakpoint
CREATE INDEX "reviews_listing_idx" ON "reviews" USING btree ("published","reviewed_at");--> statement-breakpoint
CREATE INDEX "reviews_product_offer_id_idx" ON "reviews" USING btree ("product_offer_id");
--> statement-breakpoint
